  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n2');
  // n0's request reaches n1 first; n1 votes for n0
  const msgs = await h.inFlight();
  await h.deliver(msgs.find((m) => m.from === 'n0' && m.to === 'n1')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'VoteReply' && m.to === 'n0')!.id);
