  const n2 = await h.node('n2');
  if (n2!.votedFor === 'n1') {
    assert.equal((await h.node('n1'))!.role, 'leader');
    assert.equal(v0!.leader, 'n1');
  } else assert.equal((await h.node('n1'))!.role, 'candidate');
});

test('a node that voted cannot start an election after the candidate gives up', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.giveUp('n0');
  await h.deliverAll();
  assert.equal((await h.timeout('n2')).ok, false);
});

test('crash and recover: refusals, down ignores messages, written state survives', async () => {
  const h = await createHost();
  assert.equal((await h.recover('n1')).ok, false);
  assert.equal((await h.crash('nx')).ok, false);
  assert.deepEqual(await h.crash('n1'), { ok: true });
  assert.deepEqual(await h.node('n1'), { role: 'down', term: 0, votedFor: null, leader: null });
  assert.equal((await h.crash('n1')).ok, false);
  assert.equal((await h.timeout('n1')).ok, false);
  assert.equal((await h.giveUp('n1')).ok, false);
  await h.timeout('n0');
  await h.deliverAll();
  // n1 ignored n0's request; n2 voted, so n0 leads; n1 ignored the Leader announcement too
  assert.deepEqual(await h.node('n1'), { role: 'down', term: 0, votedFor: null, leader: null });
  assert.equal((await h.node('n0'))!.role, 'leader');
  assert.deepEqual(await h.recover('n1'), { ok: true });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 0, votedFor: null, leader: null });
  assert.equal((await h.recover('n1')).ok, false);
});

test('a crashed leader recovers as a follower with its vote and leader', async () => {
  const h = await createHost();
  await h.timeout('n2');
  await h.deliverAll();
  assert.deepEqual(await h.crash('n2'), { ok: true });
  assert.deepEqual(await h.node('n2'), { role: 'down', term: 1, votedFor: 'n2', leader: 'n2' });
  await h.recover('n2');
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n2', leader: 'n2' });
  assert.equal((await h.timeout('n2')).ok, false);
});

test('a crashed candidate ignores replies and cannot lead after recovering', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.deliver((await h.inFlight()).find((m) => m.to === 'n1')!.id);
  await h.crash('n0');
  await h.deliverAll();
  await h.recover('n0');
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  await h.deliverAll();
  for (const n of NODES) assert.notEqual((await h.node(n))!.role, 'leader');
});

test('random orders: at most one leader, with a majority', async () => {
  for (let seed = 1; seed <= 40; seed++) {
    let s = seed;
    const rnd = () => ((s = (s * 1103515245 + 12345) % 2147483648) / 2147483648);
    const h = await createHost();
    const starters = NODES.filter(() => rnd() < 0.6);
    for (const n of starters) await h.timeout(n);
    for (;;) {
      const msgs = await h.inFlight();
      if (!msgs.length) break;
      if (rnd() < 0.2) { const n = NODES[Math.floor(rnd() * 3)]; await h.timeout(n); continue; }
      if (rnd() < 0.1) { const n = NODES[Math.floor(rnd() * 3)]; await h.giveUp(n); continue; }
      if (rnd() < 0.1) { const n = NODES[Math.floor(rnd() * 3)]; await h.crash(n); continue; }
      if (rnd() < 0.1) { const n = NODES[Math.floor(rnd() * 3)]; await h.recover(n); continue; }
      await h.deliver(msgs[Math.floor(rnd() * msgs.length)].id);
    }
    const views = await Promise.all(NODES.map((n) => h.node(n)));
    const leaders = NODES.filter((_, i) => views[i]!.role === 'leader');
    assert.ok(leaders.length <= 1, `seed ${seed}`);
    for (const l of leaders) assert.ok(views.filter((v) => v!.votedFor === l).length >= 2, `seed ${seed}`);
    for (const v of views) if (v!.leader !== null) assert.deepEqual(leaders, [v!.leader], `seed ${seed}`);
    for (const l of leaders) for (const v of views) assert.equal(v!.leader, l, `seed ${seed}`);
  }
});
